/**
 * @cipherbox/sdk - CipherBoxClient
 *
 * Stateful client orchestrating folder CRUD, file upload/download,
 * and event-driven change notification. Wraps @cipherbox/sdk-core
 * stateless functions with internal state management (FolderTree, KeyCache).
 *
 * Design principles:
 * - Zero React/Zustand/browser dependencies
 * - All state flows through typed events (SdkEvent)
 * - Operations are wrapped with withOperation() for consistent
 *   start/end/error event emission
 * - Key material is cleared on destroy()
 */

import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
import * as sdkCore from '@cipherbox/sdk-core';
import { clearBytes } from '@cipherbox/crypto';
import type { FolderChild } from '@cipherbox/core';
import type { CipherBoxClientConfig, FolderState } from './types';
import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
import { FolderTree } from './state/folder-tree';
import { KeyCache } from './state/key-cache';
import * as binOps from './bin';
import type { BinState } from './bin';
import * as shareOps from './share';
import type { SentShareInfo } from './share';

/** Thrown when a bin operation is attempted before loadBin() has been called. */
export class BinNotLoadedError extends Error {
  constructor() {
    super('Bin not loaded');
    this.name = 'BinNotLoadedError';
  }
}

export class CipherBoxClient {
  private config: CipherBoxClientConfig;
  private ctx: SdkContext;
  private emitter: SdkEventEmitter;
  private folderTree: FolderTree;
  private keyCache: KeyCache;
  private binState: BinState | null = null;
  /** Internal copies of key material — zeroed on destroy() without affecting caller buffers */
  private internalVaultKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
  private internalRootFolderKey: Uint8Array;

  constructor(config: CipherBoxClientConfig) {
    // Defensive copy of key material so destroy() only zeroes our copies
    this.internalVaultKeypair = {
      publicKey: new Uint8Array(config.vaultKeypair.publicKey),
      privateKey: new Uint8Array(config.vaultKeypair.privateKey),
    };
    this.internalRootFolderKey = new Uint8Array(config.rootFolderKey);
    this.config = {
      ...config,
      vaultKeypair: this.internalVaultKeypair,
      rootFolderKey: this.internalRootFolderKey,
    };
    this.ctx = {
      apiUrl: config.apiUrl,
      getAccessToken: config.getAccessToken,
    };
    this.emitter = new SdkEventEmitter();
    this.folderTree = new FolderTree();
    this.keyCache = new KeyCache();
  }

  // ---- Event subscription ----

  /** Subscribe to SDK events. Returns an unsubscribe function. */
  on(handler: SdkEventHandler): () => void {
    return this.emitter.on(handler);
  }

  /** Unsubscribe a previously registered handler. */
  off(handler: SdkEventHandler): void {
    this.emitter.off(handler);
  }

  // ---- Lifecycle ----

  // ---- Share re-wrapping (internal) ----

  /**
   * Re-wrap keys for share recipients after adding items to a folder.
   *
   * Queries the share callbacks for active shares covering the folder,
   * then wraps each new item's plaintext key for each recipient.
   * Failures are logged but do not propagate (re-wrapping is best-effort).
   */
  private async reWrapNewItems(
    folderIpnsName: string,
    items: Array<{ keyType: 'file' | 'folder'; itemId: string; plaintextKey: Uint8Array }>
  ): Promise<void> {
    const callbacks = this.config.shareCallbacks;
    if (!callbacks) return;

    const coveringShares = await callbacks.getCoveringShares(folderIpnsName);
    if (coveringShares.length === 0) return;

    const { failedRecipients } = await shareOps.reWrapForRecipients({
      coveringShares,
      newItems: items,
      addShareKeysFn: callbacks.addShareKeys,
    });

    if (failedRecipients.length > 0) {
      console.warn(
        `[SDK] Re-wrapping failed for ${failedRecipients.length} recipient(s):`,
        failedRecipients.map((k) => k.slice(0, 10) + '...')
      );
      this.emitter.emit({
        type: 'share:reWrapFailed',
        folderIpnsName,
        failedRecipients,
      } as SdkEvent);
    }
  }

  /**
   * Destroy the client, clearing all sensitive state.
   * After calling destroy(), the client instance should not be reused.
   */
  destroy(): void {
    this.folderTree.clear();
    this.keyCache.clear();
    this.emitter.removeAll();
    // Zero internal key copies (defense-in-depth; JS GC may retain copies)
    // Only zeroes our copies, not the caller-provided buffers
    this.internalVaultKeypair.privateKey.fill(0);
    this.internalVaultKeypair.publicKey.fill(0);
    this.internalRootFolderKey.fill(0);
    this.binState = null;
  }

  /**
   * Check if the SDK already has state for a folder.
   *
   * @param ipnsName - Folder's IPNS name
   * @returns true if the folder is registered in the SDK's FolderTree
   */
  hasFolder(ipnsName: string): boolean {
    return this.folderTree.has(ipnsName);
  }

  /**
   * Get the current sequence number for a folder in the SDK's internal state.
   * Returns undefined if the folder is not registered.
   */
  getFolderSequenceNumber(ipnsName: string): bigint | undefined {
    return this.folderTree.get(ipnsName)?.sequenceNumber;
  }

  /**
   * Get the IPNS private key for a folder in the SDK's internal state.
   * Returns undefined if the folder is not registered or has no key.
   *
   * Used by ensureFolderRegistered to preserve SDK's correct IPNS key
   * when the store has an empty placeholder (SDK-created folders store
   * keys internally, not in Zustand).
   */
  getFolderIpnsPrivateKey(ipnsName: string): Uint8Array | undefined {
    const key = this.folderTree.get(ipnsName)?.ipnsKeypair?.privateKey;
    return key && key.length > 0 ? key : undefined;
  }

  /**
   * Register an externally-loaded folder into the SDK's internal state.
   *
   * Used when folder metadata is loaded outside the SDK (e.g., by a navigation
   * hook) but the SDK needs to know about the folder for mutation operations
   * (create, rename, move, delete, upload).
   *
   * This is a bridge method for gradual SDK adoption -- eventually all folder
   * loading should go through client.loadFolder().
   *
   * @param ipnsName - Folder's IPNS name
   * @param folderKey - Decrypted AES-256 folder key
   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
   * @param children - Current folder children
   * @param sequenceNumber - Current IPNS sequence number
   */
  registerFolder(
    ipnsName: string,
    folderKey: Uint8Array,
    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array },
    children: FolderChild[],
    sequenceNumber: bigint
  ): void {
    this.folderTree.set(ipnsName, {
      ipnsName,
      folderKey,
      ipnsKeypair,
      sequenceNumber,
      children,
      metadata: null,
      lastLoadedAt: Date.now(),
    });
  }

  // ---- Internal state access (for bin/share modules) ----

  /** @internal Get the folder tree for bin/share operations */
  getFolderTree(): FolderTree {
    return this.folderTree;
  }

  /** @internal Get the SDK context */
  getContext(): SdkContext {
    return this.ctx;
  }

  /** @internal Get the client config */
  getConfig(): CipherBoxClientConfig {
    return this.config;
  }

  /** @internal Emit an event (used by bin/share modules) */
  emitEvent(event: SdkEvent): void {
    this.emitter.emit(event);
  }

  // ---- Folder operations ----

  /**
   * Load a folder's metadata from IPNS.
   *
   * Resolves the folder's IPNS record, decrypts metadata, stores state
   * internally, and emits a 'folder:loaded' event.
   *
   * @param ipnsName - Folder's IPNS name
   * @param folderKey - Decrypted AES-256 folder key
   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
   * @returns The loaded folder state, or null if IPNS record not found
   */
  async loadFolder(
    ipnsName: string,
    folderKey: Uint8Array,
    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array }
  ): Promise<FolderState | null> {
    return this.withOperation('loadFolder', async () => {
      const result = await sdkCore.loadFolderMetadata({
        ipnsName,
        folderKey,
        ctx: this.ctx,
      });

      if (!result) return null;

      const state: FolderState = {
        ipnsName,
        folderKey,
        ipnsKeypair,
        sequenceNumber: result.sequenceNumber,
        children: result.metadata.children,
        metadata: result.metadata,
        lastLoadedAt: Date.now(),
      };

      this.folderTree.set(ipnsName, state);

      this.emitter.emit({
        type: 'folder:loaded',
        folderId: ipnsName,
        ipnsName,
        children: result.metadata.children,
        sequenceNumber: result.sequenceNumber,
      });

      return state;
    });
  }

  /**
   * Create a new subfolder inside an existing folder.
   *
   * Generates IPNS keypair and folder key, wraps with user's public key,
   * adds folder entry to parent metadata, publishes parent IPNS record,
   * and publishes empty folder metadata for the new subfolder.
   *
   * @param parentIpnsName - IPNS name of the parent folder
   * @param name - Name for the new subfolder
   * @returns Created folder's UUID, IPNS name, folder key, and IPNS private key
   */
  async createFolder(
    parentIpnsName: string,
    name: string
  ): Promise<{ id: string; ipnsName: string; folderKey: Uint8Array; ipnsPrivateKey: Uint8Array }> {
    return this.withOperation('createFolder', async () => {
      const parent = this.folderTree.get(parentIpnsName);
      if (!parent) throw new Error('Parent folder not loaded');

      // 1. Create subfolder (generates keys, wraps with user public key)
      const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
        await sdkCore.createSubfolder({
          name,
          userPublicKey: this.config.vaultKeypair.publicKey,
          teeKeys: this.config.teeKeys,
        });

      // 2. Check for duplicate name
      if (parent.children.some((child) => child.name === name)) {
        throw new Error('An item with this name already exists');
      }

      // 3. Add folder entry to parent's children
      const updatedChildren: FolderChild[] = [...parent.children, folder];

      // 3. Update parent metadata and publish
      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
        children: updatedChildren,
        folderKey: parent.folderKey,
        ipnsPrivateKey: parent.ipnsKeypair.privateKey,
        ipnsName: parentIpnsName,
        sequenceNumber: parent.sequenceNumber,
        ctx: this.ctx,
        encryptedIpnsPrivateKey: encryptedIpnsPrivateKey,
        keyEpoch,
      });

      // 4. Update parent state
      parent.children = updatedChildren;
      parent.sequenceNumber = newSequenceNumber;
      parent.lastLoadedAt = Date.now();
      this.folderTree.set(parentIpnsName, parent);

      // 5. Publish empty metadata for the new subfolder
      await sdkCore.updateFolderMetadataAndPublish({
        children: [],
        folderKey,
        ipnsPrivateKey,
        ipnsName: folder.ipnsName,
        sequenceNumber: 0n,
        ctx: this.ctx,
        encryptedIpnsPrivateKey,
        keyEpoch,
      });

      // 7. Emit parent folder updated event
      this.emitter.emit({
        type: 'folder:updated',
        folderId: parentIpnsName,
        ipnsName: parentIpnsName,
        children: updatedChildren,
        sequenceNumber: newSequenceNumber,
      });

      // 8. Re-wrap subfolder key for share recipients (non-blocking)
      if (this.config.shareCallbacks) {
        // Don't await — re-wrapping shouldn't block folder creation return
        this.reWrapNewItems(parentIpnsName, [
          { keyType: 'folder', itemId: folder.id, plaintextKey: folderKey },
        ]).catch((err) => {
          console.warn('[SDK] Post-createFolder re-wrapping failed:', err);
        });
      }

      return { id: folder.id, ipnsName: folder.ipnsName, folderKey, ipnsPrivateKey };
    });
  }

  /**
   * Rename a child entry (folder or file) in a folder.
   *
   * Updates the name in the folder's metadata and publishes the change.
   *
   * @param folderIpnsName - IPNS name of the folder containing the item
   * @param childId - ID of the child to rename
   * @param newName - New name for the child
   */
  async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> {
    return this.withOperation('renameItem', async () => {
      const folder = this.folderTree.get(folderIpnsName);
      if (!folder) throw new Error('Folder not loaded');

      // 1. Rename in metadata (pure operation)
      const { updatedChildren } = sdkCore.renameInFolder({
        children: folder.children,
        childId,
        newName,
      });

      // 2. Publish updated metadata
      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
        children: updatedChildren,
        folderKey: folder.folderKey,
        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
        ipnsName: folderIpnsName,
        sequenceNumber: folder.sequenceNumber,
        ctx: this.ctx,
      });

      // 3. Update internal state
      folder.children = updatedChildren;
      folder.sequenceNumber = newSequenceNumber;
      folder.lastLoadedAt = Date.now();
      this.folderTree.set(folderIpnsName, folder);

      // 4. Emit update event
      this.emitter.emit({
        type: 'folder:updated',
        folderId: folderIpnsName,
        ipnsName: folderIpnsName,
        children: updatedChildren,
        sequenceNumber: newSequenceNumber,
      });
    });
  }

  /**
   * Move a child entry between two folders.
   *
   * Removes from source, adds to destination, publishes both IPNS records
   * (destination first for crash safety -- add-before-remove pattern).
   *
   * @param sourceIpnsName - IPNS name of the source folder
   * @param destIpnsName - IPNS name of the destination folder
   * @param childId - ID of the child to move
   */
  async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
    return this.withOperation('moveItem', async () => {
      const source = this.folderTree.get(sourceIpnsName);
      const dest = this.folderTree.get(destIpnsName);
      if (!source) throw new Error('Source folder not loaded');
      if (!dest) throw new Error('Destination folder not loaded');

      // 1. Compute updated children for both folders (pure operation)
      const { updatedSourceChildren, updatedDestChildren } = sdkCore.moveItem({
        sourceChildren: source.children,
        destChildren: dest.children,
        childId,
      });

      // 2. Publish destination first (add-before-remove for crash safety)
      const destResult = await sdkCore.updateFolderMetadataAndPublish({
        children: updatedDestChildren,
        folderKey: dest.folderKey,
        ipnsPrivateKey: dest.ipnsKeypair.privateKey,
        ipnsName: destIpnsName,
        sequenceNumber: dest.sequenceNumber,
        ctx: this.ctx,
      });

      // 3. Publish source (remove)
      const sourceResult = await sdkCore.updateFolderMetadataAndPublish({
        children: updatedSourceChildren,
        folderKey: source.folderKey,
        ipnsPrivateKey: source.ipnsKeypair.privateKey,
        ipnsName: sourceIpnsName,
        sequenceNumber: source.sequenceNumber,
        ctx: this.ctx,
      });

      // 4. Update internal state
      source.children = updatedSourceChildren;
      source.sequenceNumber = sourceResult.newSequenceNumber;
      dest.children = updatedDestChildren;
      dest.sequenceNumber = destResult.newSequenceNumber;
      this.folderTree.set(sourceIpnsName, source);
      this.folderTree.set(destIpnsName, dest);

      // 5. Emit events for both folders
      this.emitter.emit({
        type: 'folder:updated',
        folderId: sourceIpnsName,
        ipnsName: sourceIpnsName,
        children: updatedSourceChildren,
        sequenceNumber: sourceResult.newSequenceNumber,
      });
      this.emitter.emit({
        type: 'folder:updated',
        folderId: destIpnsName,
        ipnsName: destIpnsName,
        children: updatedDestChildren,
        sequenceNumber: destResult.newSequenceNumber,
      });
    });
  }

  /**
   * Delete a child entry from a folder's metadata.
   *
   * This is a simple metadata delete -- it does NOT move to bin.
   * Use deleteToBin() for soft-delete with bin support.
   *
   * @param folderIpnsName - IPNS name of the folder containing the item
   * @param childId - ID of the child to delete
   * @returns The removed child entry
   */
  async deleteItem(folderIpnsName: string, childId: string): Promise<{ removedItem: FolderChild }> {
    return this.withOperation('deleteItem', async () => {
      const folder = this.folderTree.get(folderIpnsName);
      if (!folder) throw new Error('Folder not loaded');

      // 1. Remove from metadata (pure operation)
      const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
        children: folder.children,
        childId,
      });

      // 2. Publish updated metadata
      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
        children: updatedChildren,
        folderKey: folder.folderKey,
        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
        ipnsName: folderIpnsName,
        sequenceNumber: folder.sequenceNumber,
        ctx: this.ctx,
      });

      // 3. Update internal state
      folder.children = updatedChildren;
      folder.sequenceNumber = newSequenceNumber;
      folder.lastLoadedAt = Date.now();
      this.folderTree.set(folderIpnsName, folder);

      // 4. Emit update event
      this.emitter.emit({
        type: 'folder:updated',
        folderId: folderIpnsName,
        ipnsName: folderIpnsName,
        children: updatedChildren,
        sequenceNumber: newSequenceNumber,
      });

      return { removedItem };
    });
  }

  // ---- File operations ----

  /**
   * Upload a file to a folder.
   *
   * Encrypts the file, uploads to IPFS, creates per-file IPNS metadata,
   * adds a FilePointer to the parent folder's metadata, and publishes.
   *
   * @param folderIpnsName - IPNS name of the target folder
   * @param data - Raw file content as Uint8Array
   * @param fileName - Display name for the file
   * @param mimeType - MIME type of the file
   * @param onProgress - Optional upload progress callback
   * @returns CID of the uploaded encrypted file
   */
  async uploadFile(
    folderIpnsName: string,
    data: Uint8Array,
    fileName: string,
    mimeType: string,
    onProgress?: ProgressCallback
  ): Promise<{ cid: string }> {
    return this.withOperation('uploadFile', async () => {
      const folder = this.folderTree.get(folderIpnsName);
      if (!folder) throw new Error('Folder not loaded');

      if (folder.children.some((child) => child.name === fileName)) {
        throw new Error('An item with this name already exists');
      }

      const fileId = crypto.randomUUID();

      // 1. Encrypt and upload file, create file metadata
      const uploadResult = await sdkCore.uploadFile({
        data,
        fileId,
        mimeType,
        folderKey: folder.folderKey,
        userPublicKey: this.config.vaultKeypair.publicKey,
        ctx: this.ctx,
        onProgress,
        teeKeys: this.config.teeKeys,
      });

      // 2. Add FilePointer to folder's children
      const { updatedChildren } = sdkCore.addFilePointerToFolder({
        children: folder.children,
        fileId,
        fileName,
        fileMetaIpnsName: uploadResult.fileMetaIpnsName,
        ipnsPrivateKeyEncrypted: uploadResult.ipnsPrivateKeyEncrypted,
      });

      // 3. Batch publish: file metadata IPNS + folder metadata IPNS
      await sdkCore.batchPublishIpnsRecords([uploadResult.ipnsRecord]);

      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
        children: updatedChildren,
        folderKey: folder.folderKey,
        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
        ipnsName: folderIpnsName,
        sequenceNumber: folder.sequenceNumber,
        ctx: this.ctx,
      });

      // 4. Update internal state
      folder.children = updatedChildren;
      folder.sequenceNumber = newSequenceNumber;
      folder.lastLoadedAt = Date.now();
      this.folderTree.set(folderIpnsName, folder);

      // 5. Emit events
      this.emitter.emit({
        type: 'file:uploaded',
        folderId: folderIpnsName,
        fileName,
        cid: uploadResult.cid,
      });
      this.emitter.emit({
        type: 'folder:updated',
        folderId: folderIpnsName,
        ipnsName: folderIpnsName,
        children: updatedChildren,
        sequenceNumber: newSequenceNumber,
      });

      // 6. Re-wrap file key for share recipients (best-effort)
      try {
        if (this.config.shareCallbacks) {
          await this.reWrapNewItems(folderIpnsName, [
            { keyType: 'file', itemId: fileId, plaintextKey: uploadResult.fileKey },
          ]);
        }
      } catch (err) {
        console.warn('[SDK] Post-upload re-wrapping failed:', err);
      } finally {
        clearBytes(uploadResult.fileKey);
      }

      return { cid: uploadResult.cid };
    });
  }

  /**
   * Download a file using its per-file IPNS metadata.
   *
   * Resolves the file's IPNS record, decrypts the metadata with the
   * folder key, then downloads and decrypts the file content.
   * This is the primary download path for v2 folder metadata.
   *
   * @param fileMetaIpnsName - IPNS name of the file's metadata record
   * @param folderKey - Parent folder's decrypted AES-256 key
   * @param onProgress - Optional download progress callback
   * @returns Decrypted file content
   */
  async downloadFromIpns(
    fileMetaIpnsName: string,
    folderKey: Uint8Array,
    onProgress?: DownloadProgressCallback
  ): Promise<Uint8Array> {
    return this.withOperation('downloadFromIpns', async () => {
      // 1. Resolve per-file IPNS to get FileMetadata
      const resolved = await sdkCore.resolveFileMetadata(fileMetaIpnsName, folderKey, this.ctx);

      // 2. Download and decrypt file content
      const plaintext = await sdkCore.downloadAndDecrypt({
        cid: resolved.metadata.cid,
        fileKeyEncrypted: resolved.metadata.fileKeyEncrypted,
        fileIv: resolved.metadata.fileIv,
        userPrivateKey: this.config.vaultKeypair.privateKey,
        encryptionMode: resolved.metadata.encryptionMode,
        ctx: this.ctx,
        onProgress,
      });

      this.emitter.emit({ type: 'file:downloaded', cid: resolved.metadata.cid });
      return plaintext;
    });
  }

  /**
   * Download and decrypt a file from IPFS.
   *
   * Fetches the encrypted file content, unwraps the file key using the
   * user's private key, and decrypts the content.
   *
   * @param cid - IPFS CID of the encrypted file content
   * @param fileKeyEncrypted - Hex-encoded ECIES-wrapped file key
   * @param fileIv - Hex-encoded IV used for encryption
   * @param encryptionMode - 'GCM' (default) or 'CTR'
   * @param onProgress - Optional download progress callback
   * @returns Decrypted file content
   */
  async downloadFile(
    cid: string,
    fileKeyEncrypted: string,
    fileIv: string,
    encryptionMode?: 'GCM' | 'CTR',
    onProgress?: DownloadProgressCallback
  ): Promise<Uint8Array> {
    return this.withOperation('downloadFile', async () => {
      const plaintext = await sdkCore.downloadAndDecrypt({
        cid,
        fileKeyEncrypted,
        fileIv,
        userPrivateKey: this.config.vaultKeypair.privateKey,
        encryptionMode,
        ctx: this.ctx,
        onProgress,
      });

      this.emitter.emit({ type: 'file:downloaded', cid });

      return plaintext;
    });
  }

  // ---- Bin operations ----

  /**
   * Load the recycle bin metadata.
   *
   * Always returns a BinState — if no bin IPNS record exists yet,
   * returns empty state so deleteToBin can create the first record.
   */
  async loadBin(): Promise<BinState> {
    return this.withOperation('loadBin', async () => {
      const result = await binOps.loadBin({
        binCtx: this.getBinContext(),
      });

      this.binState = result;
      this.emitter.emit({ type: 'bin:updated', entries: result.entries });

      return result;
    });
  }

  /**
   * Soft-delete an item by moving it to the recycle bin.
   *
   * Removes the item from the folder's metadata, adds a BinEntry,
   * and publishes both folder and bin IPNS records.
   *
   * @param folderIpnsName - IPNS name of the folder containing the item
   * @param childId - ID of the child to delete
   * @param parentPath - Breadcrumb path for restore (e.g., "My Vault / Documents")
   */
  async deleteToBin(folderIpnsName: string, childId: string, parentPath: string): Promise<void> {
    return this.withOperation('deleteToBin', async () => {
      if (!this.binState) throw new BinNotLoadedError();

      const { updatedBinState } = await binOps.addToBin({
        folderIpnsName,
        childId,
        parentPath,
        folderTree: this.folderTree,
        binState: this.binState,
        binCtx: this.getBinContext(),
      });

      this.binState = updatedBinState;

      // Emit events
      const folderState = this.folderTree.get(folderIpnsName);
      this.emitter.emit({
        type: 'folder:updated',
        folderId: folderIpnsName,
        ipnsName: folderIpnsName,
        children: folderState?.children ?? [],
        sequenceNumber: folderState?.sequenceNumber ?? 0n,
      });
      this.emitter.emit({ type: 'bin:updated', entries: updatedBinState.entries });
    });
  }

  /**
   * Restore an item from the recycle bin to its target folder.
   *
   * @param entryId - ID of the bin entry to restore
   * @param targetFolderIpnsName - IPNS name of the folder to restore to
   */
  async restoreFromBin(entryId: string, targetFolderIpnsName: string): Promise<void> {
    return this.withOperation('restoreFromBin', async () => {
      if (!this.binState) throw new BinNotLoadedError();

      const { updatedBinState } = await binOps.restoreFromBin({
        entryId,
        targetFolderIpnsName,
        folderTree: this.folderTree,
        binState: this.binState,
        binCtx: this.getBinContext(),
      });

      this.binState = updatedBinState;

      // Emit events
      const targetState = this.folderTree.get(targetFolderIpnsName);
      this.emitter.emit({
        type: 'folder:updated',
        folderId: targetFolderIpnsName,
        ipnsName: targetFolderIpnsName,
        children: targetState?.children ?? [],
        sequenceNumber: targetState?.sequenceNumber ?? 0n,
      });
      this.emitter.emit({ type: 'bin:updated', entries: updatedBinState.entries });
    });
  }

  /**
   * Permanently delete a bin entry (unpin CIDs, remove from bin).
   *
   * @param entryId - ID of the bin entry to permanently delete
   */
  async permanentDelete(entryId: string): Promise<void> {
    return this.withOperation('permanentDelete', async () => {
      if (!this.binState) throw new BinNotLoadedError();

      const { updatedBinState } = await binOps.permanentDeleteFromBin({
        entryId,
        binState: this.binState,
        binCtx: this.getBinContext(),
      });

      this.binState = updatedBinState;
      this.emitter.emit({ type: 'bin:updated', entries: updatedBinState.entries });
    });
  }

  /**
   * Permanently delete all bin entries.
   */
  async emptyBin(): Promise<void> {
    return this.withOperation('emptyBin', async () => {
      if (!this.binState) throw new BinNotLoadedError();

      const { updatedBinState } = await binOps.emptyBin({
        binState: this.binState,
        binCtx: this.getBinContext(),
      });

      this.binState = updatedBinState;
      this.emitter.emit({ type: 'bin:updated', entries: [] });
    });
  }

  // ---- Share operations ----

  /**
   * Create an ECIES-wrapped key for sharing a folder with a recipient.
   *
   * @param folderIpnsName - IPNS name of the folder to share
   * @param recipientPublicKey - Recipient's secp256k1 public key
   * @returns Hex-encoded wrapped key for the recipient
   */
  async shareFolder(
    folderIpnsName: string,
    recipientPublicKey: Uint8Array
  ): Promise<{ encryptedKey: string }> {
    return this.withOperation('shareFolder', async () => {
      const folder = this.folderTree.get(folderIpnsName);
      if (!folder) throw new Error('Folder not loaded');

      return shareOps.createShareKey({
        folderKey: folder.folderKey,
        recipientPublicKey,
        folderIpnsName,
        shareCtx: this.getShareContext(),
      });
    });
  }

  /**
   * Revoke a share (soft-delete).
   *
   * @param shareId - Share ID to revoke
   * @param revokeShareFn - Function to call the API revoke endpoint
   */
  async revokeShare(
    shareId: string,
    revokeShareFn: (shareId: string) => Promise<void>
  ): Promise<void> {
    return this.withOperation('revokeShare', async () => {
      await shareOps.revokeShare({ shareId, revokeShareFn });
    });
  }

  /**
   * Re-wrap keys for share recipients after adding items to a shared folder.
   *
   * @param coveringShares - Active shares covering the folder
   * @param newItems - New items whose keys need re-wrapping
   * @param addShareKeysFn - Function to add wrapped keys to a share via API
   */
  async reWrapForRecipients(
    coveringShares: SentShareInfo[],
    newItems: Array<{ keyType: 'file' | 'folder'; itemId: string; plaintextKey: Uint8Array }>,
    addShareKeysFn: (
      shareId: string,
      keys: Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>
    ) => Promise<void>
  ): Promise<{ failedRecipients: string[] }> {
    return this.withOperation('reWrapForRecipients', async () => {
      return shareOps.reWrapForRecipients({
        coveringShares,
        newItems,
        addShareKeysFn,
      });
    });
  }

  // ---- Private helpers ----

  /** Build bin operation context from client config */
  private getBinContext(): binOps.BinOperationContext {
    return {
      ctx: this.ctx,
      userPrivateKey: this.config.vaultKeypair.privateKey,
      userPublicKey: this.config.vaultKeypair.publicKey,
      rootFolderKey: this.config.rootFolderKey,
      teeKeys: this.config.teeKeys,
    };
  }

  /** Build share operation context from client config */
  private getShareContext(): shareOps.ShareOperationContext {
    return {
      ctx: this.ctx,
      userPrivateKey: this.config.vaultKeypair.privateKey,
      userPublicKey: this.config.vaultKeypair.publicKey,
    };
  }

  // ---- Operation wrapper ----

  /**
   * Wrap an async operation with event emission and error handling.
   *
   * Emits 'operation:start' before, 'operation:end' on success (with duration),
   * and 'error' on failure. Also calls the config callbacks if provided.
   */
  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
    const start = Date.now();
    this.config.onOperationStart?.(name);
    this.emitter.emit({ type: 'operation:start', operation: name });

    try {
      const result = await fn();
      const durationMs = Date.now() - start;
      this.config.onOperationEnd?.(name);
      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
      return result;
    } catch (error) {
      this.config.onError?.(error as Error);
      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
      throw error;
    }
  }
}

import { test, expect, Browser } from '@playwright/test';
import {
  createWalletTestAccount,
  closeWalletTestAccounts,
  navigateToShared,
  navigateToFiles,
  type WalletTestAccount,
} from '../utils/multi-account-wallet';
import { createTestTextFile, createTestImageFile, cleanupTestFiles } from '../utils/test-files';
import { FileListPage } from '../page-objects/file-browser/file-list.page';
import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
import { ShareDialogPage } from '../page-objects/dialogs/share-dialog.page';
import { SharedFileBrowserPage } from '../page-objects/file-browser/shared-file-browser.page';

/**
 * Sharing Workflow E2E Test Suite
 *
 * Tests user-to-user sharing with multiple authenticated accounts.
 * Each test account gets its own browser context (isolated cookies/storage).
 *
 * Accounts:
 * - Alice: primary sharer (creates content and shares it)
 * - Bob: primary recipient (receives and browses shared content)
 * - Charlie: secondary recipient (for multi-recipient tests)
 *
 * Test flow:
 * 1. Setup: Create 3 accounts, Alice creates test content
 * 2. Basic sharing: Alice shares file with Bob, Bob receives it
 * 3. Folder sharing: Alice shares folder tree, Bob navigates it
 * 4. Multi-recipient: Alice adds Charlie to existing share
 * 5. Revocation: Alice revokes Bob's access
 * 6. Post-share mutations: Alice adds files to shared folder
 * 7. Error cases: Invalid key, self-share, user not found
 * 8. Hide share: Bob hides a shared item
 */
test.describe.serial('Sharing Workflow', () => {
  let browser: Browser;
  let alice: WalletTestAccount;
  let bob: WalletTestAccount;
  let charlie: WalletTestAccount;

  // Page objects per account
  let aliceFileList: FileListPage;
  let aliceUploadZone: UploadZonePage;
  let aliceContextMenu: ContextMenuPage;
  let aliceCreateFolderDialog: CreateFolderDialogPage;
  let aliceShareDialog: ShareDialogPage;

  let bobSharedBrowser: SharedFileBrowserPage;
  let bobContextMenu: ContextMenuPage;

  let charlieSharedBrowser: SharedFileBrowserPage;

  // Test data - unique per run
  const runId = Date.now().toString();

  // Shared file
  const sharedFileName = `shared-file-${runId}.txt`;
  const sharedFileContent = 'This file is shared with Bob';

  // Shared folder structure
  const sharedFolderName = `shared-folder-${runId}`;
  const subFolderName = `subfolder-${runId}`;
  const folderFile1Name = `folder-file1-${runId}.txt`;
  const folderFile2Name = `subfolder-file-${runId}.txt`;

  // Post-share file (added after share is created)
  const postShareFileName = `added-after-share-${runId}.txt`;
  const postShareFileContent = 'This file was added after the share was created';

  // Preview test files (image in shared folder)
  const sharedImageName = `test-image-${runId}.png`;

  // Helper to truncate a public key for matching in the UI
  function truncateKey(key: string): string {
    const hex = key.startsWith('0x') ? key.slice(2) : key;
    return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
  }

  // ============================================
  // Alice helpers
  // ============================================

  async function aliceCreateFolder(name: string): Promise<void> {
    const newFolderButton = alice.page.locator('.file-browser-new-folder-button');
    await newFolderButton.click();
    await aliceCreateFolderDialog.waitForOpen();
    await aliceCreateFolderDialog.createFolder(name);
    await aliceFileList.waitForItemToAppear(name, { timeout: 30000 });
  }

  async function aliceUploadFile(fileName: string, content: string): Promise<void> {
    const testFile = createTestTextFile(fileName, content);
    await aliceUploadZone.uploadFile(testFile.path);

    // Wait for upload: check for either the file appearing or an error alert
    await Promise.race([
      aliceFileList.waitForItemToAppear(fileName, { timeout: 30000 }),
      alice.page
        .locator('[role="alert"]')
        .waitFor({ state: 'visible', timeout: 30000 })
        .then(async () => {
          const alertText = await alice.page.locator('[role="alert"]').textContent();
          throw new Error(`Upload failed with alert: ${alertText}`);
        }),
    ]);
  }

  async function aliceNavigateIntoFolder(name: string): Promise<void> {
    await aliceFileList.doubleClickFolder(name);
    // Wait for breadcrumbs to show the folder name
    await alice.page.locator('.breadcrumb-item', { hasText: name.toLowerCase() }).waitFor({
      state: 'visible',
      timeout: 30000,
    });
  }

  async function aliceNavigateBack(): Promise<void> {
    await alice.page.locator('[data-testid="parent-dir-row"]').dblclick();
    await alice.page.waitForTimeout(500);
  }

  async function aliceOpenShareDialog(itemName: string): Promise<void> {
    await aliceFileList.rightClickItem(itemName);
    await aliceContextMenu.waitForOpen();
    await aliceContextMenu.clickShare();
    await aliceShareDialog.waitForOpen();
    await aliceShareDialog.waitForRecipientsLoaded();
  }

  // ============================================
  // Setup and Teardown
  // ============================================

  test.beforeAll(async ({ browser: testBrowser }) => {
    browser = testBrowser;
  });

  test.afterAll(async () => {
    cleanupTestFiles();
    if (alice || bob || charlie) {
      await closeWalletTestAccounts([alice, bob, charlie].filter(Boolean));
    }
  });

  // ============================================
  // Phase 1: Account Setup
  // ============================================

  test('1.1 Create test accounts (Alice, Bob, Charlie)', async () => {
    test.setTimeout(180_000); // 3 wallet logins with Core Kit init
    // Create accounts sequentially (each needs its own context + wallet login)
    alice = await createWalletTestAccount(browser, 'alice');
    bob = await createWalletTestAccount(browser, 'bob');
    charlie = await createWalletTestAccount(browser, 'charlie');

    // Initialize page objects for Alice
    aliceFileList = new FileListPage(alice.page);
    aliceUploadZone = new UploadZonePage(alice.page);
    aliceContextMenu = new ContextMenuPage(alice.page);
    aliceCreateFolderDialog = new CreateFolderDialogPage(alice.page);
    aliceShareDialog = new ShareDialogPage(alice.page);

    // Initialize page objects for Bob
    bobSharedBrowser = new SharedFileBrowserPage(bob.page);
    bobContextMenu = new ContextMenuPage(bob.page);

    // Initialize page objects for Charlie
    charlieSharedBrowser = new SharedFileBrowserPage(charlie.page);

    // Verify all three accounts have different public keys
    expect(alice.publicKey).not.toBe(bob.publicKey);
    expect(alice.publicKey).not.toBe(charlie.publicKey);
    expect(bob.publicKey).not.toBe(charlie.publicKey);
  });

  // ============================================
  // Phase 2: Alice Creates Content
  // ============================================

  test('2.1 Alice creates a test file at root', async () => {
    await aliceUploadFile(sharedFileName, sharedFileContent);
    expect(await aliceFileList.isItemVisible(sharedFileName)).toBe(true);
  });

  test('2.2 Alice creates a folder with nested content', async () => {
    // Create top-level folder
    await aliceCreateFolder(sharedFolderName);
    expect(await aliceFileList.isItemVisible(sharedFolderName)).toBe(true);

    // Navigate into it and add a file + an image
    await aliceNavigateIntoFolder(sharedFolderName);
    await aliceUploadFile(folderFile1Name, 'File inside shared folder');

    // Upload a PNG image (needed for shared preview test in Phase 11)
    const testImage = createTestImageFile(sharedImageName);
    await aliceUploadZone.uploadFile(testImage.path);
    await aliceFileList.waitForItemToAppear(sharedImageName, { timeout: 30000 });

    // Create subfolder
    await aliceCreateFolder(subFolderName);

    // Navigate into subfolder and add a file
    await aliceNavigateIntoFolder(subFolderName);
    await aliceUploadFile(folderFile2Name, 'File inside subfolder');

    // Navigate back to root
    await aliceNavigateBack(); // back to shared folder
    await aliceNavigateBack(); // back to root
  });

  // ============================================
  // Phase 3: Basic File Sharing
  // ============================================

  test('3.1 Alice shares a file with Bob', async () => {
    await aliceOpenShareDialog(sharedFileName);

    // Should start with no recipients
    expect(await aliceShareDialog.getRecipientCount()).toBe(0);

    // Share with Bob
    await aliceShareDialog.shareWithKey(bob.publicKey);
    const successText = await aliceShareDialog.waitForSuccess({ timeout: 30000 });
    expect(successText).toContain(truncateKey(bob.publicKey));

    // Verify recipient appears in the list
    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
    const recipientKeys = await aliceShareDialog.getRecipientKeys();
    expect(recipientKeys[0]).toBe(truncateKey(bob.publicKey));

    await aliceShareDialog.close();
  });

  test('3.2 Bob sees the shared file in ~/shared', async () => {
    await navigateToShared(bob);

    // Wait for the shared items to load
    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });

    // Bob should see Alice's shared file
    await bobSharedBrowser.waitForSharedItem(sharedFileName, { timeout: 15000 });
    expect(await bobSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);

    // Verify [RO] badge
    const roBadge = bobSharedBrowser.getReadOnlyBadge(sharedFileName);
    expect(await roBadge.isVisible()).toBe(true);

    // Verify "SHARED BY" shows Alice's truncated key
    const sharedBy = await bobSharedBrowser.getSharedBy(sharedFileName);
    expect(sharedBy).toContain(truncateKey(alice.publicKey));
  });

  // ============================================
  // Phase 4: Folder Sharing with Descendants
  // ============================================

  test('4.1 Alice shares a folder with Bob', async () => {
    // Make sure Alice is on files page
    await navigateToFiles(alice);
    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });

    await aliceOpenShareDialog(sharedFolderName);

    // Share with Bob - folder sharing re-wraps descendant keys
    await aliceShareDialog.shareWithKey(bob.publicKey);

    // Wait for progress (folder sharing re-wraps keys for each child)
    // The progress may be very fast for small folders, so we just wait for success
    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
    expect(successText).toContain(truncateKey(bob.publicKey));

    await aliceShareDialog.close();
  });

  test('4.2 Bob navigates the shared folder tree', async () => {
    // Navigate to Bob's shared view
    await navigateToShared(bob);
    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });

    // Find and open the shared folder
    await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });

    // Click the shared item and wait — IPNS resolution can be slow on first access
    await bobSharedBrowser.openSharedItem(sharedFolderName);
    await bob.page.waitForTimeout(3000);

    // If IPNS resolution failed on first try, retry once
    const parentDirVisible = await bobSharedBrowser.parentDirRow().isVisible();
    if (!parentDirVisible) {
      await navigateToShared(bob);
      await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
      await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
      await bobSharedBrowser.navigateIntoFolder(sharedFolderName);
    }

    // Should see folder contents: the file and subfolder
    const itemNames = await bobSharedBrowser.getFolderItemNames();
    expect(itemNames.some((n) => n.includes(folderFile1Name))).toBe(true);
    expect(itemNames.some((n) => n.includes(subFolderName))).toBe(true);

    // Navigate into subfolder
    await bobSharedBrowser.doubleClickFolderItem(subFolderName);
    // Wait for subfolder content to load
    await bob.page.waitForTimeout(2000);

    const subItems = await bobSharedBrowser.getFolderItemNames();
    expect(subItems.some((n) => n.includes(folderFile2Name))).toBe(true);

    // Navigate back to shared root
    await bobSharedBrowser.navigateToRoot();
    await bobSharedBrowser.waitForLoaded({ timeout: 15000 });
  });

  // ============================================
  // Phase 5: Multi-Recipient (Add Charlie)
  // ============================================

  test('5.1 Alice adds Charlie as a second recipient', async () => {
    await navigateToFiles(alice);
    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });

    await aliceOpenShareDialog(sharedFolderName);

    // Bob should already be a recipient
    await aliceShareDialog.waitForRecipientsLoaded();
    expect(await aliceShareDialog.getRecipientCount()).toBe(1);

    // Add Charlie
    await aliceShareDialog.shareWithKey(charlie.publicKey);
    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
    expect(successText).toContain(truncateKey(charlie.publicKey));

    // Now should have 2 recipients
    expect(await aliceShareDialog.getRecipientCount()).toBe(2);

    await aliceShareDialog.close();
  });

  test('5.2 Charlie sees the shared folder', async () => {
    await navigateToShared(charlie);
    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });

    await charlieSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
    expect(await charlieSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
  });

  // ============================================
  // Phase 6: Revoke Access
  // ============================================

  test("6.1 Alice revokes Bob's access to the shared folder", async () => {
    await navigateToFiles(alice);
    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });

    await aliceOpenShareDialog(sharedFolderName);
    await aliceShareDialog.waitForRecipientsLoaded();

    // Should have 2 recipients (Bob + Charlie)
    expect(await aliceShareDialog.getRecipientCount()).toBe(2);

    // Revoke Bob
    const bobTruncated = truncateKey(bob.publicKey);
    await aliceShareDialog.revokeRecipient(bobTruncated);

    // Should now have 1 recipient (Charlie only)
    expect(await aliceShareDialog.getRecipientCount()).toBe(1);

    await aliceShareDialog.close();
  });

  test('6.2 Bob no longer sees the shared folder', async () => {
    // Reload Bob's shared view to get fresh data
    await navigateToShared(bob);
    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });

    // The shared folder should no longer appear for Bob
    // (may still show the shared file from test 3.1)
    const itemNames = await bobSharedBrowser.getSharedItemNames();
    const hasFolderShare = itemNames.some((n) => n.includes(sharedFolderName));
    expect(hasFolderShare).toBe(false);
  });

  test('6.3 Charlie still has access', async () => {
    await navigateToShared(charlie);
    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });

    await charlieSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
    expect(await charlieSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
  });

  // ============================================
  // Phase 7: Post-Share Mutations
  // ============================================

  test('7.1 Alice adds a file to the shared folder after sharing', async () => {
    await navigateToFiles(alice);
    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });

    // Navigate into the shared folder
    await aliceNavigateIntoFolder(sharedFolderName);

    // Upload a new file
    await aliceUploadFile(postShareFileName, postShareFileContent);
    expect(await aliceFileList.isItemVisible(postShareFileName)).toBe(true);

    // Navigate back
    await aliceNavigateBack();
  });

  test('7.2 Charlie sees the newly added file', async () => {
    // IPNS propagation on staging can take many seconds after Alice's
    // upload in 7.1. Retry navigation into the shared folder to trigger
    // fresh IPNS resolves until the post-share file appears.
    test.setTimeout(120000);
    await charlie.page.waitForTimeout(3000);

    const maxAttempts = 3;
    let found = false;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      // Navigate Charlie into the shared folder
      await navigateToShared(charlie);
      await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
      await charlieSharedBrowser.navigateIntoFolder(sharedFolderName);

      // Wait for the post-share file to appear
      try {
        await charlieSharedBrowser
          .getFolderItem(postShareFileName)
          .waitFor({ state: 'visible', timeout: 30000 });
        found = true;
        break;
      } catch {
        // IPNS hasn't propagated yet — navigate back and retry
        if (attempt < maxAttempts) {
          await charlieSharedBrowser.navigateToRoot();
          await charlie.page.waitForTimeout(5000);
        }
      }
    }

    expect(found).toBe(true);
    await charlieSharedBrowser.navigateToRoot();
  });

  test('7.3 Charlie can preview the post-share file (re-wrapping verification)', async () => {
    // This test verifies the re-wrapping fix: files uploaded AFTER sharing
    // must have their keys re-wrapped for recipients. Without the fix,
    // Charlie would see "No re-wrapped file key available" error.
    await navigateToShared(charlie);
    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
    await charlieSharedBrowser.navigateIntoFolder(sharedFolderName);

    // Wait for the post-share file to be visible
    await charlieSharedBrowser
      .getFolderItem(postShareFileName)
      .waitFor({ state: 'visible', timeout: 15000 });

    // Right-click and open the text file via Edit (opens read-only for shared files)
    await charlieSharedBrowser.rightClickFolderItem(postShareFileName);
    const charlieContextMenu = new ContextMenuPage(charlie.page);
    await charlieContextMenu.waitForOpen();
    await charlieContextMenu.clickEdit();

    // The text editor dialog should open in read-only mode
    const editorDialog = charlie.page.locator('.text-editor-modal');
    await editorDialog.waitFor({ state: 'visible', timeout: 30000 });

    // Verify the content loaded (not an error message).
    // The textarea appears immediately but content loads async (IPFS download + decrypt).
    // Wait for the textarea to contain the expected text, not just be visible.
    const textarea = charlie.page.locator('.text-editor-textarea');
    await textarea.waitFor({ state: 'visible', timeout: 15000 });
    await expect(textarea).toHaveValue(/added after the share/, { timeout: 15000 });

    // Close the dialog
    await charlie.page.locator('.text-editor-modal .modal-close').click();
    await editorDialog.waitFor({ state: 'hidden' });

    await charlieSharedBrowser.navigateToRoot();
  });

  // ============================================
  // Phase 8: Error Cases
  // ============================================

  test('8.1 Invalid public key format shows error', async () => {
    await navigateToFiles(alice);
    await aliceFileList.waitForItemToAppear(sharedFileName, { timeout: 15000 });

    await aliceOpenShareDialog(sharedFileName);

    // Try an invalid key
    await aliceShareDialog.shareWithKey('0x1234invalid');
    const errorText = await aliceShareDialog.waitForError();
    expect(errorText).toContain('invalid key format');

    await aliceShareDialog.close();
  });

  test('8.2 Self-sharing shows error', async () => {
    await aliceOpenShareDialog(sharedFileName);

    // Try sharing with own key
    await aliceShareDialog.shareWithKey(alice.publicKey);
    const errorText = await aliceShareDialog.waitForError();
    expect(errorText).toContain('cannot share with yourself');

    await aliceShareDialog.close();
  });

  test('8.3 Unregistered user shows error', async () => {
    await aliceOpenShareDialog(sharedFileName);

    // Use a valid-format key that doesn't belong to any user
    // 0x04 + 128 hex chars (65 bytes uncompressed secp256k1)
    const fakeKey =
      '0x04' +
      'aa'.repeat(32) + // x coordinate
      'bb'.repeat(32); // y coordinate

    await aliceShareDialog.shareWithKey(fakeKey);
    const errorText = await aliceShareDialog.waitForError({ timeout: 15000 });
    expect(errorText).toContain('user not found');

    await aliceShareDialog.close();
  });

  // ============================================
  // Phase 9: Hide Share
  // ============================================

  test('9.1 Bob hides the shared file', async () => {
    await navigateToShared(bob);
    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });

    // Bob should still see the shared file from test 3.1
    await bobSharedBrowser.waitForSharedItem(sharedFileName, { timeout: 15000 });

    // Right-click and hide
    await bobSharedBrowser.rightClickSharedItem(sharedFileName);
    await bobContextMenu.waitForOpen();
    await bobContextMenu.clickHide();

    // Wait for the item to disappear
    await bobSharedBrowser.waitForSharedItemGone(sharedFileName, { timeout: 10000 });
  });

  // ============================================
  // Phase 10: Re-share After Revoke
  // ============================================

  test('10.1 Alice re-shares the folder with Bob after previous revoke', async () => {
    await navigateToFiles(alice);
    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });

    await aliceOpenShareDialog(sharedFolderName);

    // Charlie should be the only recipient (Bob was revoked in 6.1)
    await aliceShareDialog.waitForRecipientsLoaded();
    expect(await aliceShareDialog.getRecipientCount()).toBe(1);

    // Re-share with Bob
    await aliceShareDialog.shareWithKey(bob.publicKey);
    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
    expect(successText).toContain(truncateKey(bob.publicKey));

    // Now should have 2 recipients again
    expect(await aliceShareDialog.getRecipientCount()).toBe(2);

    await aliceShareDialog.close();
  });

  test('10.2 Bob sees the re-shared folder', async () => {
    await navigateToShared(bob);
    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });

    await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
    const itemNames = await bobSharedBrowser.getSharedItemNames();
    const hasFolderShare = itemNames.some((n) => n.includes(sharedFolderName));
    expect(hasFolderShare).toBe(true);
  });

  // ============================================
  // Phase 11: Shared File Previews
  // ============================================

  test('11.1 Bob can see the image in the shared folder', async () => {
    // The image was uploaded in test 2.2 before sharing, so share keys exist.
    // Bob should be able to see it in the shared folder view.
    await navigateToShared(bob);
    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });

    // Navigate into the shared folder
    await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
    await bobSharedBrowser.openSharedItem(sharedFolderName);
    await bob.page.waitForTimeout(3000);

    // Check if we navigated successfully
    const parentVisible = await bobSharedBrowser.parentDirRow().isVisible();
    if (!parentVisible) {
      await bobSharedBrowser.openSharedItem(sharedFolderName);
      await bobSharedBrowser.parentDirRow().waitFor({ state: 'visible', timeout: 30000 });
    }

    // Verify the image file is visible
    await bobSharedBrowser.getFolderItem(sharedImageName).waitFor({
      state: 'visible',
      timeout: 15000,
    });
  });

  test('11.2 Bob previews a text file in the shared folder', async () => {
    // Bob is already inside the shared folder from test 11.1
    // Right-click the text file and open context menu
    await bobSharedBrowser.rightClickFolderItem(folderFile1Name);
    await bobContextMenu.waitForOpen();

    // Verify Edit option is available for text files (opens read-only for shared files)
    const options = await bobContextMenu.getVisibleOptions();
    expect(options).toContain('Edit');

    // Click Edit to open text viewer (read-only in shared context)
    await bobContextMenu.clickEdit();

    // Wait for the text editor modal to appear
    const modal = bob.page.locator('.text-editor-modal');
    await modal.waitFor({ state: 'visible', timeout: 30000 });

    // Verify it opened in read-only mode
    const title = await bob.page.locator('.modal-title').textContent();
    expect(title).toContain('View:');

    // Wait for decryption to complete (loading state to disappear)
    await bob.page.locator('.text-editor-loading').waitFor({ state: 'hidden', timeout: 30000 });

    // Verify textarea is read-only
    const textarea = bob.page.locator('.text-editor-textarea');
    await textarea.waitFor({ state: 'visible' });
    const isReadOnly = await textarea.getAttribute('readonly');
    expect(isReadOnly).not.toBeNull();

    // Verify the status bar shows read-only
    const statusText = await bob.page.locator('.text-editor-status').textContent();
    expect(statusText).toContain('read-only');

    // Verify the content was decrypted (textarea has some text)
    const content = await textarea.inputValue();
    expect(content.length).toBeGreaterThan(0);

    // Close the dialog
    await bob.page.locator('.dialog-button--primary', { hasText: 'close' }).click();
    await modal.waitFor({ state: 'hidden' });
  });

  test('11.3 Bob previews an image in the shared folder', async () => {
    // Bob is already inside the shared folder from test 11.1
    // The image was uploaded before sharing (test 2.2), so share keys exist.
    await bobSharedBrowser.getFolderItem(sharedImageName).waitFor({
      state: 'visible',
      timeout: 15000,
    });

    // Right-click the image file
    await bobSharedBrowser.rightClickFolderItem(sharedImageName);
    await bobContextMenu.waitForOpen();

    // Verify Preview option is available
    const options = await bobContextMenu.getVisibleOptions();
    expect(options).toContain('Preview');

    // Click Preview to open image preview
    await bobContextMenu.clickPreview();

    // Wait for the image preview modal to appear
    const modal = bob.page.locator('.image-preview-modal');
    await modal.waitFor({ state: 'visible', timeout: 30000 });

    // Wait for decryption to complete (loading or error state)
    await bob.page
      .locator('.image-preview-img, .image-preview-error')
      .first()
      .waitFor({ state: 'visible', timeout: 30000 });

    // Verify the image element is rendered (not an error)
    const img = bob.page.locator('.image-preview-img');
    expect(await img.isVisible()).toBe(true);

    // Verify the image has a valid src (blob URL)
    const src = await img.getAttribute('src');
    expect(src).toContain('blob:');

    // Close the dialog
    await bob.page.locator('.modal-close').click();
    await modal.waitFor({ state: 'hidden' });
  });

  test('11.4 Shared text file context menu shows View not Edit', async () => {
    // Bob should still be inside the shared folder
    await bobSharedBrowser.getFolderItem(folderFile1Name).waitFor({
      state: 'visible',
      timeout: 15000,
    });

    // Right-click the text file
    await bobSharedBrowser.rightClickFolderItem(folderFile1Name);
    await bobContextMenu.waitForOpen();

    // In read-only mode, Edit menu item should be present (opens read-only viewer)
    // but Rename and Delete should NOT be present
    const options = await bobContextMenu.getVisibleOptions();
    expect(options).toContain('Edit');
    expect(options).toContain('Download');
    expect(options).not.toContain('Preview');
    expect(options).not.toContain('Rename');
    expect(options).not.toContain('Delete');

    // Click Edit to open the read-only text viewer
    await bobContextMenu.clickEdit();

    const modal = bob.page.locator('.text-editor-modal');
    await modal.waitFor({ state: 'visible', timeout: 30000 });

    // Verify read-only title
    const title = await bob.page.locator('.modal-title').textContent();
    expect(title).toContain('View:');

    // Close
    await bob.page.locator('.dialog-button--primary', { hasText: 'close' }).click();
    await modal.waitFor({ state: 'hidden' });
  });
});

